import { Tooltip as RechartsTooltip } from "recharts";
import { useTheme } from "@theme";

import { TooltipProps } from "../chart.types";

const Tooltip = (props: TooltipProps) => {
  const theme = useTheme();

  return (
    <RechartsTooltip
      contentStyle={{
        borderRadius: theme.toRem(theme.border.radius.sm),
        ...props.contentStyle,
      }}
      cursor={{ fill: theme.color.background.defaultHover }}
      {...props}
    />
  );
};

Tooltip.displayName = "Tooltip";

export default Tooltip;
